'use strict';
const H={clamp:(x,a,b)=>Math.max(a,Math.min(b,x))};
const p={"x":1,"y":1,"elbow":"up"};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先检查目标是否可达
Object.assign(s, ((s,p)=>({radius:Math.hypot(p.x,p.y),reachable:Math.hypot(p.x,p.y)<=2}))(s, p));
// 用余弦定理解肘角
Object.assign(s, ((s,p)=>({q2:s.reachable?(p.elbow==='up'?1:-1)*Math.acos(H.clamp((s.radius*s.radius-2)/2,-1,1)):null}))(s, p));
// 补回肩角
Object.assign(s, ((s,p)=>({q1:s.reachable?Math.atan2(p.y,p.x)-Math.atan2(Math.sin(s.q2),1+Math.cos(s.q2)):null}))(s, p));
// 用正运动学独立回代
Object.assign(s, ((s,p)=>({end:s.reachable?[Math.cos(s.q1)+Math.cos(s.q1+s.q2),Math.sin(s.q1)+Math.sin(s.q1+s.q2)]:null,elbow:s.reachable?[Math.cos(s.q1),Math.sin(s.q1)]:null}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={mean:xs=>xs.reduce((a,b)=>a+b,0)/xs.length};
const p={"offset":1,"outlier":0};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 显式给定点对应关系
Object.assign(s, ((s,p)=>({source:[0,1,2],target:[p.offset,1+p.offset,2+p.offset+p.outlier]}))(s, p));
// 每对点提供一个位移候选
Object.assign(s, ((s,p)=>({differences:s.target.map((v,i)=>v-s.source[i])}))(s, p));
// 比较均值与中位数平移
Object.assign(s, ((s,p)=>({leastSquares:H.mean(s.differences),robust:s.differences.slice().sort((a,b)=>a-b)[1]}))(s, p));
// 回算配准残差
Object.assign(s, ((s,p)=>({residuals:s.target.map((v,i)=>v-(s.source[i]+s.leastSquares)),robustResiduals:s.target.map((v,i)=>v-(s.source[i]+s.robust))}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"mu":0.5,"normal":5,"mass":0.4};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 画出对称双指夹持的受力
Object.assign(s, ((s,p)=>({weight:p.mass*9.81}))(s, p));
// 计算单侧摩擦锥边界
Object.assign(s, ((s,p)=>({perFinger:p.mu*p.normal}))(s, p));
// 两侧共同抵抗重力
Object.assign(s, ((s,p)=>({capacity:2*s.perFinger,margin:2*s.perFinger-s.weight}))(s, p));
// 保留模型假设和裕量
Object.assign(s, ((s,p)=>({staticFeasible:s.margin>=0,requiredPerFinger:s.weight/(2*p.mu)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0),
dist:(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]),
segmentDistance:(a,b,c)=>{const dx=b[0]-a[0],dy=b[1]-a[1],den=dx*dx+dy*dy,t=den?Math.max(0,Math.min(1,((c[0]-a[0])*dx+(c[1]-a[1])*dy)/den)):0;return Math.hypot(a[0]+t*dx-c[0],a[1]+t*dy-c[1]);}};
const p={"radius":0.4,"clearance":0.1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 给出起终点和两条候选路径
Object.assign(s, ((s,p)=>({paths:[[[0,0],[2,0]],[[0,0],[0,1],[2,1],[2,0]]],center:[1,0]}))(s, p));
// 检查整段距离
Object.assign(s, ((s,p)=>({distances:s.paths.map(path=>Math.min(...path.slice(1).map((b,i)=>H.segmentDistance(path[i],b,s.center))))}))(s, p));
// 同时计算可行性和长度
Object.assign(s, ((s,p)=>({valid:s.distances.map(d=>d>p.radius+p.clearance),lengths:s.paths.map(path=>H.sum(path.slice(1).map((b,i)=>H.dist(path[i],b))))}))(s, p));
// 只在可行路径里选择最短
Object.assign(s, ((s,p)=>({selected:s.valid.map((ok,i)=>ok?i:-1).filter(i=>i>=0).sort((a,b)=>s.lengths[a]-s.lengths[b])[0]??null}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"duration":2,"position":0.5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 选一个零端点速度的时间标度
Object.assign(s, ((s,p)=>({sigma:p.position,t:p.position*p.duration}))(s, p));
// 计算三次位置曲线
Object.assign(s, ((s,p)=>({q:3*s.sigma*s.sigma-2*s.sigma**3}))(s, p));
// 求速度与加速度
Object.assign(s, ((s,p)=>({velocity:(6*s.sigma-6*s.sigma*s.sigma)/p.duration,acceleration:(6-12*s.sigma)/(p.duration*p.duration)}))(s, p));
// 检查峰值速度
Object.assign(s, ((s,p)=>({peakVelocity:1.5/p.duration,withinLimit:1.5/p.duration<=1}))(s, p));
